['def issubset(self, other):
    return self <= frozenset(other)

def issuperset(self, other):
    return self >= frozenset(other)

def union(self, *others):
    res = self
    for o in others:
        res |= frozenset(o)
    return res

def intersection(self, *others):
    res = self
    for o in others:
        res &= frozenset(o)
    return res

def difference(self, *others):
    res = self
    for o in others:
        res -= frozenset(o)
    return res

def symmetric_difference(self, other):
    return self ^ frozenset(other)
