', "def lists(n):
    l = [0]*n
    while True:
        yield l[:]
        for i in reversed(xrange(n)):
            if l[i] != n-1:
                break
            l[i] = 0
        else:
            # All digits were n-1; we're done
            return
        l[i] += 1
"]

