['class BitArray(object):
    def __init__(self, array):
        """Takes a bytearray object storing the bit data"""
        self.array = array

    def setbit(self, pos, value):
        byte, bit = divmod(pos, 8)
        if value:
            self.array[byte] |= (128 >> bit)
        else:
            self.array[byte] &= ~(128 >> bit)
