import threading

count = 0

class Screen(threading.Thread):
    def __init__(self, count):
        threading.Thread.__init__(self)
        self.count = count

    def do_something(self):
        while True:
            time.sleep(1)
            self.count += 1
            if self.count >=3:
                print "Stop!"
                break

    def run(self):
        self.do_something()

def test():
    thread1 = Screen(count)
    thread1.start()

test()
']

