["def fixList(inputList, splitChar='X'):
    outputList = inputList[:]
    x = None 
    for i in xrange(len(outputList)):
        if outputList[i] == splitChar:
            outputList[i] = x = 0 
        elif x is None:
            continue 
        else:
            outputList[i] = x 
            x += 1
    return outputList
"]

