    c = float(v) / size * 100 
    if c > 0.50:
        ChkResult = False
        tag = string2bytes(k).upper()
        r[tag] = c

# print result
if ChkResult:
    print "OK"
else:
    for x in sorted(r.keys()):
        print "    0x%s is %.2f%%"%((x), r[x])

print "Done in %.2f seconds."%(time.time() - startTime)
